CustomField.formula:
/* 3 or more connectors */ IF( ( IF(INCLUDES(Connectors__c, "Outlook"), 1, 0) + IF(INCLUDES(Connectors__c, "OneDrive"), 1, 0) + IF(INCLUDES(Connectors__c, "Salesforce"), 1, 0) + IF(INCLUDES(Connectors__c, "Web Search Access"), 1, 0) + IF(INCLUDES(Connectors__c, "Microsoft Teams"), 1, 0) + IF(INCLUDES(Connectors__c, "Vendome"), 1, 0) + IF(INCLUDES(Connectors__c, "SAM"), 1, 0) + IF(INCLUDES(Connectors__c, "OLYMPIA"), 1, 0) + IF(INCLUDES(Connectors__c, "SharePoint"), 1, 0) + IF(INCLUDES(Connectors__c, "MCP / Other"), 1, 0) ) >= 3, 1, 0 )
/* Outlook exposure */ + IF( INCLUDES(Connectors__c, "Outlook"), 2, 0 )
/* Web Search exposure */ + IF( INCLUDES(Connectors__c, "Web Search Access"), 1, 0 )
/* Web Search + internal source */ + IF( AND( INCLUDES(Connectors__c, "Web Search Access"), OR( INCLUDES(Connectors__c, "Outlook"), INCLUDES(Connectors__c, "OneDrive"), INCLUDES(Connectors__c, "Salesforce"), INCLUDES(Connectors__c, "Microsoft Teams"), INCLUDES(Connectors__c, "Vendome"), INCLUDES(Connectors__c, "SAM"), INCLUDES(Connectors__c, "OLYMPIA"), INCLUDES(Connectors__c, "SharePoint"), INCLUDES(Connectors__c, "MCP / Other") ) ), 2, 0 )
